// =========================================================================
// 1. CHECK INCOMING REQUEST BODY OR RESET ACTION
// =========================================================================
let reqBody = msg.payload || {};

// Check if a reset command was sent (e.g., setting colors to white or explicit reset flag)
let isReset = reqBody.reset === true || reqBody.action === "reset";

let responseData = {};

if (isReset) {
    // =====================================================================
    // RESET LOGIC: Set all colors to white
    // =====================================================================
    node.status({ fill: "grey", shape: "ring", text: "Resetting to white" });

    responseData = {
        colorBio: "white",
        colorPaper: "white",
        colorDomestic: "white",
        colorPlastic: "white" // ADJUST FIELD NAMES HERE AS NEEDED
    };
} else {
    // =====================================================================
    // STANDARD STATUS LOGIC: Return current colors (Integrate schedule data here)
    // =====================================================================
    node.status({ fill: "green", shape: "dot", text: "Serving status payload" });

    responseData = {
        // ADJUST OR ADD THE TRASH CATEGORY NAMES AND COLORS BELOW:
        colorBio: "green",
        colorPaper: "yellow",
        colorDomestic: "red",
        colorPlastic: "blue"
    };
}

// Attach to msg.payload for the HTTP Response node
msg.payload = responseData;
return msg;
